css:
.simple-member-card {
    padding: 20px;
    font-family: Arial, sans-serif;
    color: #333333;
}

.header h2 {
    margin: 0;
    color: #222222;
}

.sub-header {
    margin-top: 5px;
    color: #666666;
}

.section h3 {
    margin-top: 15px;
    margin-bottom: 10px;
    font-size: 16px;
    color: #444444;
}

.section p {
    margin: 6px 0;
    font-size: 14px;
}

hr {
    border: none;
    border-top: 1px solid #e0e0e0;
    margin: 15px 0;
}
